mapper.select:
SELECT T1.FINPROD_ID, T1.FINPROD_NAME, T1.FINPROD_ABBR, T1.FINPROD_TYPE2, T1.FINPROD_MARKET_ID, T1.ISSUER, T1.ISSUE_AMT, T1.VDATE, T1.MDATE, T1.CCY, T2.TYPE_6,
T2.TYPE_9, T2.TYPE_10, T2.TYPE_11, T2.TYPE_12,
T3.CUSTOMER_NAME ISSUER_NAME,
FPR.recommender recommender, FPR.recommenderName recommenderName,
T5.RATE*100 RATE, T7.CUSTOMER_NAME SPONSOR_NAME FROM FIN_PRODUCT T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO T3 ON T1.ISSUER = T3.CUSTOMER_ID LEFT JOIN FIN_CASH_INFO T4 ON T4.FINPROD_ID = T1.FINPROD_ID
AND T4.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T5 ON T5.CASH_ID = T4.CASH_ID AND T5.EFF_DATE = T1.VDATE
LEFT JOIN ( SELECT FPR.FINPROD_ID, group_concat(FPR.RECOMMENDER order by FPR.RECOMMENDER separator '，') recommender, group_concat(MCP.COUNTER_NAME order by FPR.RECOMMENDER separator '，') recommenderName FROM FIN_PRODUCT_RECOMMENT FPR LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID GROUP BY FPR.FINPROD_ID ) FPR ON FPR.FINPROD_ID = T1.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO T7 ON T7.CUSTOMER_ID = T1.SPONSOR
AND T1.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND T2.TYPE_6 = #{type6,jdbcType=VARCHAR}
AND T2.TYPE_9 in
#{item}
AND T2.TYPE_10 in
#{item}
AND T2.TYPE_11 in
#{item}
AND T1.CCY = #{ccy,jdbcType=VARCHAR}
AND T1.VDATE >= STR_TO_DATE(#{vdateStart},'%Y-%m-%d')
AND T1.VDATE <= STR_TO_DATE(#{vdateEnd},'%Y-%m-%d')
AND (T1.MDATE >= STR_TO_DATE(#{mdateStart},'%Y-%m-%d') or T1.MDATE is null)
AND (T1.MDATE <= STR_TO_DATE(#{mdateEnd},'%Y-%m-%d') or T1.MDATE is null)
AND T1.FINPROD_MARKET_ID like concat(concat('%',#{finprodId,jdbcType=VARCHAR}),'%')
AND T1.FINPROD_NAME like concat(concat('%',#{finprodName,jdbcType=VARCHAR}),'%')
AND T1.ISSUER = #{issuer,jdbcType=VARCHAR}
